## Code Example
```javascript
// Skeleton: Azure Function triggered by Event Grid blob creation
module.exports = async function processUpload(context) {
  const blobPath = context.bindingData.blobTrigger;
  const tenantId = extractTenantId(blobPath);

  const config = await appConfig.getConfiguration(tenantId);
